import json
from collections import defaultdict

BASE = '/root/autodl-tmp/provenance_weight_training/output/models'

def dedup(data):
    boundaries = [0]
    for i in range(1, len(data)):
        if data[i]['step'] < data[i-1]['step']:
            boundaries.append(i)
    if len(boundaries) == 1:
        se = defaultdict(list)
        for d in data:
            se[d['step']].append(d)
        dd = []
        for step in sorted(se.keys()):
            dd.extend(se[step][:4])
        return dd, len(boundaries)
    else:
        r0e = boundaries[1]
        frs = boundaries[-1]
        rs = data[frs]['step']
        ini = defaultdict(list)
        for d in data[:r0e]:
            if d['step'] < rs:
                ini[d['step']].append(d)
        fin = defaultdict(list)
        for d in data[frs:]:
            fin[d['step']].append(d)
        dd = []
        for step in sorted(ini.keys()):
            dd.extend(ini[step][:4])
        for step in sorted(fin.keys()):
            dd.extend(fin[step][:4])
        return dd, len(boundaries)

# Check all adaptive experiments for batch counts close to 25991
import os
for exp in sorted(os.listdir(BASE)):
    p = os.path.join(BASE, exp, 'step_metrics.jsonl')
    if not os.path.exists(p):
        continue
    with open(p) as f:
        raw = [json.loads(line) for line in f]
    dd, nb = dedup(raw)
    n = len(dd)
    if 25000 <= n <= 27000 or 'adaptive' in exp:
        # read config
        cfg_path = os.path.join(BASE, exp, 'config.json')
        tau = '?'
        method = '?'
        if os.path.exists(cfg_path):
            with open(cfg_path) as f:
                cfg = json.load(f)
                tau = cfg.get('tau', '?')
                method = cfg.get('weighting_method', '?')
        print(f'{exp}: {n} batches (raw={len(raw)}, restarts={nb}), tau={tau}, method={method}')
